{"content":"package config

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func env(m map[string]string) func(string) string { return func(k string) string { return m[k] } }

func TestLoadDefaults(t *testing.T) {
	c, err := Load(env(nil))
	if err != nil || c.Host != "localhost" || c.Port != 8080 || c.Workers != 4 {
		t.Fatalf("%+v %v", c, err)
	}
	if c.Timeout != 30*time.Second {
		t.Fatalf("Timeout = %v, want 30s", c.Timeout)
	}
	if c.Tags != nil {
		t.Fatalf("Tags = %v, want nil", c.Tags)
	}
}

func TestLoadOverrides(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_PORT": "9000", "APP_DEBUG": "true"}))
	if err != nil || c.Port != 9000 || !c.Debug {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadTimeoutAndTags(t *testing.T) {
	c, err := Load(env(map[string]string{
		"APP_TIMEOUT": "2m5s",
		"APP_TAGS": " a , b ,,c ",
	}))
	if err != nil {
		t.Fatal(err)
	}
	if c.Timeout != 125*time.Second {
		t.Fatalf("Timeout = %v, want 2m5s", c.Timeout)
	}
	want := []string{"a", "b", "c"}
	if len(c.Tags) != len(want) {
		t.Fatalf("Tags = %v, want %v", c.Tags, want)
	}
	for i := range want {
		if c.Tags[i] != want[i] {
			t.Fatalf("Tags = %v, want %v", c.Tags, want)
		}
	}
}

func TestLoadEmptyTags(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_TAGS": " , ,"}))
	if err != nil {
		t.Fatal(err)
	}
	if len(c.Tags) != 0 {
		t.Fatalf("Tags = %v, want empty", c.Tags)
	}
}

func TestLoadCollectsAllErrors(t *testing.T) {
	_, err := Load(env(map[string]string{
		"APP_PORT":    "abc",
		"APP_DEBUG":   "notabool",
		"APP_WORKERS": "0",
		"APP_TIMEOUT": "soon",
	}))
	if err == nil {
		t.Fatal("expected error")
	}
	msg := err.Error()
	for _, name := range []string{"APP_PORT", "APP_DEBUG", "APP_WORKERS", "APP_TIMEOUT"} {
		if !strings.Contains(msg, name) {
			t.Errorf("error %q does not mention %s", msg, name)
		}
	}
	var multi interface{ Unwrap() []error }
	if !errors.As(err, &multi) {
		t.Fatalf("error is not joinable: %T", err)
	}
	if got := len(multi.Unwrap()); got != 4 {
		t.Fatalf("joined errors = %d, want 4", got)
	}
}

func TestMerge(t *testing.T) {
	base := Config{Host: "h", Port: 1, Debug: true, Workers: 2, Timeout: time.Minute, Tags: []string{"x"}}
	override := Config{Port: 2, Timeout: 5 * time.Second, Tags: []string{"y", "z"}}
	got := Merge(base, override)
	want := Config{Host: "h", Port: 2, Debug: true, Workers: 2, Timeout: 5 * time.Second, Tags: []string{"y", "z"}}
	if got != (want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
}

func TestMergeZeroOverrideKeepsBase(t *testing.T) {
	base := Config{Host: "h", Port: 1, Debug: true, Workers: 2, Timeout: time.Minute, Tags: []string{"x"}}
	got := Merge(base, Config{})
	if got != base {
		t.Fatalf("got %+v, want %+v", got, base)
	}
}

func TestMergeNilOverrideTagsKeepsBase(t *testing.T) {
	base := Config{Host: "h", Tags: []string{"x"}}
	got := Merge(base, Config{Host: "o"})
	if len(got.Tags) != 1 || got.Tags[0] != "x" {
		t.Fatalf("Tags = %v, want [x]", got.Tags)
	}
}

func TestMergeEmptyOverrideTagsReplaces(t *testing.T) {
	base := Config{Tags: []string{"x", "y"}}
	got := Merge(base, Config{Tags: []string{}})
	if got.Tags == nil || len(got.Tags) != 0 {
		t.Fatalf("Tags = %v, want non-nil empty", got.Tags)
	}
}

func TestMergeDoesNotModifyArguments(t *testing.T) {
	base := Config{Tags: []string{"a", "b"}}
	override := Config{Tags: []string{"c"}}
	got := Merge(base, override)
	got.Tags[0] = "mutated"
	if base.Tags[0] != "a" || base.Tags[1] != "b" {
		t.Fatalf("base modified: %v", base.Tags)
	}
	if override.Tags[0] != "c" {
		t.Fatalf("override modified: %v", override.Tags)
	}
}
